// Illustrative sensitive-area dataset for the Center demo.
//
// Polygons are hand-curated bounding boxes around real-world places. They are
// NOT a substitute for authoritative GIS data — coverage is intentionally
// limited to the largest / most-relevant features in each category. For
// production replace the `features:` arrays with parsed GeoJSON from:
//   - National parks: NPS_Park_Boundaries (services1.arcgis.com NPS layer)
//   - Tribal lands:   BIA AIAN Land Areas
//   - Residential:    Census urban areas (TIGER/Line UAC) or county zoning
//   - Bans:           Hand-curated list of local moratoriums
//   - Pushback:       FracTracker datacenter community pushback dataset

import type { LatLng } from '../utils/area';

export type SensitiveCategory =
  | 'populated'
  | 'park'
  | 'tribal'
  | 'ban'
  | 'pushback';

export interface SensitiveFeature {
  id: string;
  name: string;
  category: SensitiveCategory;
  source: string;
  polygon: LatLng[];
}

export interface SensitiveLayer {
  id: SensitiveCategory;
  label: string;
  description: string;
  swatch: string;
  fill: string;
  stroke: string;
  features: SensitiveFeature[];
}

const bbox = (
  minLat: number,
  maxLat: number,
  minLng: number,
  maxLng: number,
): LatLng[] => [
  [maxLat, minLng],
  [maxLat, maxLng],
  [minLat, maxLng],
  [minLat, minLng],
];

const POPULATED_SOURCE = 'US Census urban areas (illustrative bbox)';
const NPS_SOURCE = 'NPS boundary (illustrative bbox)';
const BIA_SOURCE = 'BIA tribal lands (illustrative bbox)';
const BAN_SOURCE = 'Local moratorium / ordinance (illustrative)';
const PUSHBACK_SOURCE = 'FracTracker community pushback (illustrative)';

